int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t max_pairs) {
    size_t num_pairs = 0;
    const char *pair_start = in;

    while (num_pairs < max_pairs && pair_start != NULL) {
        const char *eq = strchr(pair_start, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - pair_start);
        keys_out[num_pairs] = malloc(klen + 1);
        if (!keys_out[num_pairs]) return -1;
        strncpy(keys_out[num_pairs], pair_start, klen);
        keys_out[num_pairs][klen] = '\0';

        const char *val_start = eq + 1;
        if (*val_start == '"') {
            val_start++;
            const char *quote = strchr(val_start, '"');
            if (!quote) return -1;
            size_t vlen = (size_t)(quote - val_start);
            vals_out[num_pairs] = malloc(vlen + 1);
            if (!vals_out[num_pairs]) {
                for (size_t i = 0; i < num_pairs; i++) free(keys_out[i]);
                return -1;
            }
            strncpy(vals_out[num_pairs], val_start, vlen);
            vals_out[num_pairs][vlen] = '\0';
        } else {
            const char *sp = strchr(val_start, ' ');
            size_t vlen = sp ? (size_t)(sp - val_start) : strlen(val_start);
            vals_out[num_pairs] = malloc(vlen + 1);
            if (!vals_out[num_pairs]) {
                for (size_t i = 0; i < num_pairs; i++) {
                    free(keys_out[i]);
                    free(vals_out[i]);
                }
                return -1;
            }
            strncpy(vals_out[num_pairs], val_start, vlen);
            vals_out[num_pairs][vlen] = '\0';
        }

        num_pairs++;
        pair_start = strchr(eq + 1, ' ');
    }

    return num_pairs;
}

